<div class="mb-8 flex flex-wrap items-end justify-between gap-4"><div><p class="text-[10px] font-bold uppercase tracking-[.2em] text-[#687158]"><?= __('My Account') ?></p><h1 class="mt-2 text-3xl font-medium"><?= __('Saved Addresses') ?></h1><p class="mt-2 text-sm text-[#77796f]"><?= __('Manage where your orders are delivered.') ?></p></div><button class="rounded-xl bg-[#687158] px-4 py-3 text-xs font-semibold text-white" onclick="document.getElementById('address-modal').classList.replace('hidden','flex')">＋ <?= __('Add new address') ?></button></div><div class="grid gap-5 md:grid-cols-2"><?php if(!$addresses): ?><div class="rounded-2xl border border-dashed border-[#d6d6cd] p-8 text-sm text-[#77796f]"><?= __('No saved addresses yet.') ?></div><?php endif; ?><?php foreach($addresses as $address): ?><article class="rounded-2xl border <?= $address['default']?'border-[#9da98d]':'border-[#e5e5dd]' ?> bg-[#fbfbf7] p-5"><div class="mb-4 flex justify-between"><div><h2 class="font-medium"><?= e($address['label']) ?></h2><?php if($address['default']): ?><span class="mt-2 inline-block text-[10px] font-bold uppercase tracking-wider text-[#687158]"><?= __('Default') ?></span><?php endif; ?></div><i data-lucide="map-pin" class="h-5 w-5 text-[#687158]"></i></div><p class="text-xs leading-6 text-[#77796f]"><?= e($address['name']) ?><br><?= e($address['line']) ?><br><?= e($address['city']) ?><?= $address['state']?', '.e($address['state']):'' ?><br><?= e($address['country']) ?><br><?= e($address['phone']) ?></p><div class="mt-5 flex gap-4 border-t border-[#e8e8e0] pt-4"><button class="customer-ajax text-xs text-[#a75b52]" data-id="<?= (int)$address['id'] ?>" data-url="<?= e(($base?:'').'/customer/ajax/address-delete') ?>"><?= __('Delete') ?></button><?php if(!$address['default']): ?><button class="customer-ajax ml-auto text-xs text-[#687158]" data-id="<?= (int)$address['id'] ?>" data-url="<?= e(($base?:'').'/customer/ajax/address-default') ?>"><?= __('Set as default') ?></button><?php endif; ?></div></article><?php endforeach; ?></div><div id="address-modal" class="fixed inset-0 z-50 hidden items-center justify-center bg-[#252820]/40 p-5"><form id="address-form" class="w-full max-w-lg rounded-2xl bg-[#fbfbf7] p-6 shadow-2xl"><div class="mb-5 flex items-center justify-between"><div><p class="text-[10px] font-bold uppercase tracking-[.2em] text-[#687158]"><?= __('Shipping') ?></p><h2 class="mt-2 text-xl font-medium"><?= __('Add new address') ?></h2></div><button type="button" onclick="document.getElementById('address-modal').classList.replace('flex','hidden')" class="text-xl">×</button></div><div id="addr-err" class="hidden mb-4 rounded-xl bg-red-50 border border-red-200 p-3 text-xs text-red-600 font-medium"></div><div class="grid gap-4 sm:grid-cols-2"><label class="grid gap-2 text-xs text-[#77796f]"><?= __('Label') ?> *<input name="label" required placeholder="<?= e(__('Home')) ?>" class="rounded-xl border border-[#deded6] bg-white p-3"></label><label class="grid gap-2 text-xs text-[#77796f]"><?= __('Full name') ?> *<input name="recipient_name" required class="rounded-xl border border-[#deded6] bg-white p-3"></label><label class="grid gap-2 text-xs text-[#77796f] sm:col-span-2"><?= __('Street address') ?> *<input name="address_line" required class="rounded-xl border border-[#deded6] bg-white p-3"></label><label class="grid gap-2 text-xs text-[#77796f]"><?= __('City') ?> *<input name="city" required class="rounded-xl border border-[#deded6] bg-white p-3"></label><label class="grid gap-2 text-xs text-[#77796f]"><?= __('State') ?><input name="state" class="rounded-xl border border-[#deded6] bg-white p-3"></label><label class="grid gap-2 text-xs text-[#77796f]"><?= __('Country') ?> *<input name="country" value="Nigeria" required class="rounded-xl border border-[#deded6] bg-white p-3"></label><label class="grid gap-2 text-xs text-[#77796f]"><?= __('Phone number') ?> *<input name="phone" required placeholder="+234 801 234 5678" pattern="^\+?[0-9\s\-]{8,20}$" class="rounded-xl border border-[#deded6] bg-white p-3"></label></div><label class="mt-4 flex gap-2 text-xs text-[#77796f]"><input type="checkbox" name="is_default" value="1"> <?= __('Set as default') ?></label><button type="submit" class="mt-6 w-full rounded-xl bg-[#687158] px-4 py-3 text-sm font-semibold text-white"><?= __('Save address') ?></button></form></div>
<script>document.getElementById('address-form')?.insertAdjacentHTML('afterbegin','<input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>">');
$('#address-form').on('submit',function(e){
  e.preventDefault();
  var $err=$('#addr-err');
  $err.addClass('hidden').text('');
  var required={label:'Label',recipient_name:'Recipient',address_line:'Address',city:'City',country:'Country',phone:'Phone'};
  for(var k in required){var v=(this[k]||{}).value?.trim();if(!v){$err.removeClass('hidden').text(required[k]+' is required.');(this[k]||{}).focus?.();return;}}
  var ph=this.phone.value.trim();
  if(!/^\+?[0-9\s\-]{8,20}$/.test(ph)){$err.removeClass('hidden').text('Enter a valid phone number (8–20 digits, numbers only).');this.phone.focus();return;}
  $.post('<?= e(($base?:'').'/customer/ajax/address-add') ?>',$(this).serialize())
    .done(function(r){customerToast(r.message||'Address saved.');setTimeout(()=>location.reload(),400)})
    .fail(function(x){$err.removeClass('hidden').text((x.responseJSON||{}).message||'Could not save address.');});
});</script>
